(7435230, 1174089, 40391, '<td valign="top">Perhaps, but I don''t think I would seek shelter from a storm there. Nice find.</td>', 'Perhaps, but I don''t think I would seek shelter from a storm there. Nice find.', '2016-02-07 06:55:07.000000', NULL, 1),
(7435231, 1174818, 40391, '<td valign="top">It does feel foreboding.</td>', 'It does feel foreboding.', '2016-02-07 06:56:20.000000', NULL, 1),
