(7435233, 1174974, 40391, '<td valign="top">It starts off feeling good but I find myself wanting something more. I still like it more than most.</td>', 'It starts off feeling good but I find myself wanting something more. I still like it more than most.', '2016-02-07 07:00:14.000000', NULL, 1),
(7435234, 1175129, 40391, '<td valign="top">I''m no meteorologist but I would call this more overcast than fine ;)<br/> <br/>Just the right amount of exposure to give movement and to keep the feeling of force.</td>', 'I''m no meteorologist but I would call this more overcast than fine ;) Just the right amount of exposure to give movement and to keep the feeling of force.', '2016-02-07 07:02:38.000000', NULL, 1),
(7435235, 1174964, 40391, '<td valign="top">The strong processing is perfect here. I love those colours.</td>', 'The strong processing is perfect here. I love those colours.', '2016-02-07 07:03:25.000000', NULL, 1),
(7435236, 1173571, 40391, '<td valign="top">It is a beautiful portrait and I rather like the overall lighting.</td>', 'It is a beautiful portrait and I rather like the overall lighting.', '2016-02-07 07:04:16.000000', NULL, 1),
(7435237, 1175214, 40391, '<td valign="top">I''m in two minds about the strong overlay but the mind that approves has a stronger voice. I really like the cat being level and the world tilting.</td>', 'I''m in two minds about the strong overlay but the mind that approves has a stronger voice. I really like the cat being level and the world tilting.', '2016-02-07 07:06:31.000000', NULL, 1),
(7435238, 1175149, 40391, '<td valign="top">The falling snow is the picture and the rest is secondary. Nicely done.</td>', 'The falling snow is the picture and the rest is secondary. Nicely done.', '2016-02-07 07:07:49.000000', NULL, 1),
(7435239, 1175160, 40391, '<td valign="top">Stunning, beautiful and intriguing.</td>', 'Stunning, beautiful and intriguing.', '2016-02-07 07:08:32.000000', NULL, 1),
(7435241, 1173802, 40391, '<td valign="top">I think they are both giving each other the cold shoulder (groan). I like the added bottle to the scene.</td>', 'I think they are both giving each other the cold shoulder (groan). I like the added bottle to the scene.', '2016-02-07 07:11:53.000000', NULL, 1),
(7435242, 1173829, 40391, '<td valign="top">I feel like I''m on Tatooine. Nice capture.</td>', 'I feel like I''m on Tatooine. Nice capture.', '2016-02-07 07:14:39.000000', NULL, 1),
(7435243, 1175219, 40391, '<td valign="top">With those shackles it doesn''t feel as free as it could be. I is a good capture though.</td>', 'With those shackles it doesn''t feel as free as it could be. I is a good capture though.', '2016-02-07 07:15:53.000000', NULL, 1),
(7435244, 1175039, 40391, '<td valign="top">You''re luckier than all those who have entered shots of frozen waste lands. Where I am, however, it''s been hotter than hell.</td>', 'You''re luckier than all those who have entered shots of frozen waste lands. Where I am, however, it''s been hotter than hell.', '2016-02-07 07:17:41.000000', NULL, 1),
(7435245, 1175142, 40391, '<td valign="top">Nicely captured and composed.</td>', 'Nicely captured and composed.', '2016-02-07 07:18:53.000000', NULL, 1),
(7435246, 1174728, 40391, '<td valign="top">Beautiful image and great perspective with that frozen person.</td>', 'Beautiful image and great perspective with that frozen person.', '2016-02-07 07:19:51.000000', NULL, 1),
